<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/CacheStore.php';require_once __DIR__.'/../core/LinkChecker.php';require_once __DIR__.'/../core/Json.php';use Core\CacheStore;use Core\LinkChecker;$args=array_slice(isset($argv)?$argv:array(),1);$quiet=false;$opts=array('limit'=>40,'budget'=>20,'stale'=>360,'pan'=>'','dry'=>false,);$argError='';$i=0;$nArgs=count($args);while($i<$nArgs){$a=(string)$args[$i];if($a==='--help'||$a==='-h'){echo"php cron/link_check.php [--limit N] [--budget N] [--stale N] [--pan quark,uc] [--dry] [--quiet]\n";exit(0);}if($a==='--quiet'||$a==='-q'){$opts['quiet']=true;$quiet=true;$i++;continue;}if($a==='--dry'){$opts['dry']=true;$i++;continue;}if(strpos($a,'--')!==0){$argError='无法识别的参数：'.$a;break;}$eq=strpos($a,'=');if($eq!==false){$key=substr($a,2,$eq-2);$val=substr($a,$eq+1);$i++;}else{$key=substr($a,2);if(!in_array($key,array('limit','budget','stale','pan'),true)){$argError='未知参数：'.$a;break;}if($i+1>=$nArgs||strpos((string)$args[$i+1],'--')===0){$argError='参数缺少值：'.$a;break;}$val=$args[$i+1];$i+=2;}if($key==='limit'||$key==='budget'||$key==='stale'){$opts[$key]=(int)$val;}elseif($key==='pan'){$opts[$key]=strtolower(trim((string)$val));}else{$argError='未知参数：--'.$key;break;}}if($argError!==''){fwrite(STDERR,$argError."\n");exit(1);}if($opts['limit']<1||$opts['limit']>200){fwrite(STDERR,"--limit 范围必须是 1~200。\n");exit(1);}if($opts['budget']<5||$opts['budget']>300){fwrite(STDERR,"--budget 范围必须是 5~300 秒。\n");exit(1);}if($opts['stale']<0){fwrite(STDERR,"--stale 不能为负数。\n");exit(1);}$start=time();$checked=0;$ok=0;$dead=0;$fail=0;$rows=CacheStore::itemsWithLinks($opts['limit']);if(!$rows&&!$quiet){echo"没有待检测的条目（download_url 全部为空，或都已在本轮预算内检查过）。\n";}foreach($rows as $row){if($checked>0&&(time()-$start)>=$opts['budget']){break;}$raw=(string)$row['download_url'];$links=array();if(strpos($raw,'[')===0){$arr=json_decode($raw,true);if(is_array($arr)){foreach($arr as $e){if(is_array($e)&&!empty($e['url'])){$links[]=array('label'=>(isset($e['label'])?$e['label']:'下载'),'url'=>(string)$e['url']);}elseif(is_string($e)&&$e!==''){$links[]=array('label'=>'下载','url'=>$e);}}}}else{foreach(preg_split('/\r?\n/',$raw)as $u){$u=trim($u);if($u!==''){$links[]=array('label'=>'下载','url'=>$u);}}}if(!$links){continue;}$results=array();foreach($links as $l){$url=trim((string)$l['url']);if($url===''){continue;}$r=LinkChecker::check($url);if($opts['pan']!==''&&!in_array($r['pan'],array_map('trim',explode(',',$opts['pan'])),true)){continue;}$results[]=array('label'=>(string)$l['label'],'url'=>$url,'ok'=>(bool)$r['ok'],'code'=>(int)$r['code'],'msg'=>(string)$r['msg'],);if(!empty($r['ok'])){$ok++;}else{$dead++;}}$checked++;if(!$results){continue;}if($opts['dry']){if(!$quiet){echo sprintf("[dry] #%d %s → 有效 %d / 失效 %d\n",(int)$row['id'],(string)$row['download_url'],count(array_filter($results,function($a){return!empty($a['ok']);})),count(array_filter($results,function($a){return empty($a['ok']);})));}continue;}try{CacheStore::saveLinkChecks((int)$row['id'],$results);}catch(\Throwable $ex){$fail++;if(!$quiet){fwrite(STDERR,"[warn] save failed for item #".(int)$row['id'].': '.$ex->getMessage()."\n");}}}$remaining=CacheStore::countPendingLinkChecks(max(1,(int)floor($opts['stale']/60)));if($quiet){echo sprintf("link_check: checked=%d ok=%d dead=%d fail=%d remaining=%d elapsed=%ds dry=%s\n",$checked,$ok,$dead,$fail,$remaining,(time()-$start),$opts['dry']?'1':'0');}else{echo"============================================\n";echo"媒资资料库 · 链接失效检测\n";echo"--------------------------------------------\n";echo"检测条目数 : {$checked}\n";echo"链接有效   : {$ok}\n";echo"链接失效   : {$dead}\n";echo"保存失败   : {$fail}\n";echo"仍有待检   : {$remaining}\n";echo"耗时       : ".(time()-$start)." 秒\n";echo"模式       : ".($opts['dry']?'只读（--dry）':'已写库')."\n";if($opts['pan']!==''){echo"网盘过滤   : ".$opts['pan']."\n";}echo"============================================\n";echo"提示：失效条目可在后台「条目匹配 → 已匹配」页按状态筛选查看。\n";}exit($fail>$checked&&$checked>0?1:0);